/** QA only: native initial carrier eligibility is not row classification or writer authority. */
final class ContextUniversalInitialCarrierMatrix {
    static Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> checks(Snapshot x,List<Snapshot> cuts,Packet common,Map<Cut,PrivatePool> pools){Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> result=new LinkedHashMap<>();List<Snapshot> all=new ArrayList<>();all.add(null);all.addAll(cuts);for(Snapshot target:all){Cut cut=target==null?Cut.of(x):Cut.of(target);ContextUniversalNativeRows.Result rows=ContextUniversalNativeRows.inspect(x,target,64,WORK);if(rows.classified){ContextUniversalNativeRowsRunner.audit(rows);++ContextUniversalContinuationMatrix.checks;}result.put(cut,ContextUniversalFrozenConstraints.closeSignedInstantiatedUnits(rows,common,pools.get(cut),null,16,16,512,256,WORK));}return result;}
    static ContextUniversalCompoundExchange.SessionCollection compounds(Snapshot x,Packet p,Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> checks,int alternatives,int depth,int work){return ContextUniversalCompoundExchange.collectWithValidationReuse(x,p,new ArrayList<>(checks.keySet()),checks,512,alternatives,depth,work,4096);}
    static ContextUniversalSignedUnitExchange.SessionCollection units(Snapshot x,Packet p,Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> checks){return ContextUniversalSignedUnitExchange.collectWithValidationReuse(x,p,new ArrayList<>(checks.keySet()),checks,512,256,16,WORK,4096);}
    static void refused(Snapshot x,Packet p,Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> checks,String why){ContextUniversalCompoundExchange.SessionCollection c=compounds(x,p,checks,256,16,WORK);ContextUniversalSignedUnitExchange.SessionCollection u=units(x,p,checks);require(!c.collection.collected&&c.collection.output==null&&c.metrics.entries==0&&!u.collection.collected&&u.collection.output==null&&u.metrics.entries==0,why+": "+c.collection.reason);}
    static void noClosure(org.kanger.ContextUniversalFrozenConstraints.Result r,String why){require(!r.closed&&r.proofs.isEmpty()&&r.emptyProofs.isEmpty()&&!r.xRefuted&&!r.foreignRefuted,why+": "+r.reason);}
    static Frame entry(ContextUniversalSignedAlternativesMatrix.Fixture f,List<Snapshot> order){Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> checks=checks(f.x,order,f.common,f.pools);for(org.kanger.ContextUniversalFrozenConstraints.Result r:checks.values())require(r.closed&&!r.xRefuted&&!r.foreignRefuted&&r.input.classified&&r.input.withinShape,r.reason);ContextUniversalCompoundExchange.SessionCollection c=compounds(f.x,f.common,checks,256,16,WORK);ContextUniversalSignedUnitExchange.SessionCollection u=units(f.x,f.common,checks);require(c.collection.collected&&u.collection.collected&&c.metrics.entries==0&&u.metrics.entries==0&&c.metrics.verified>0&&u.metrics.verified>0,c.collection.reason+u.collection.reason);ContextUniversalCompoundExchange.Exchange e=c.collection.output;require(e.x==f.x&&e.common==f.common&&e.checks.equals(checks)&&e.clauses.size()==4&&u.collection.output.units.isEmpty()&&u.collection.output.checks.equals(checks),"actual complete SAME-ledger initial four compounds/zero symbolic units");
        Map<Set<Source>,Integer> expected=new HashMap<>();expected.put(ContextUniversalSourceAlternativesMatrix.sources(f.x.primary.get(1).source),0);expected.put(ContextUniversalSourceAlternativesMatrix.sources(f.x.primary.get(1).source,f.a.primary.get(0).source),1);expected.put(ContextUniversalSourceAlternativesMatrix.sources(f.x.primary.get(1).source,f.b.primary.get(0).source),1);expected.put(ContextUniversalSourceAlternativesMatrix.sources(f.x.primary.get(1).source,f.d.primary.get(0).source),1);List<org.kanger.ContextProductionCapture.Support> actual=new ArrayList<>();List<ContextUniversalCompoundExchange.ResidualProof> donors=new ArrayList<>();int originProofs=0;
        for(ContextUniversalCompoundExchange.ResidualProof proof:e.clauses){actual.add(proof.support);require(proof.owner.proofs.contains(proof.proof)&&proof.clause==proof.proof.clause&&proof.support==proof.proof.support,"actual original owning proof/Source references, no invented carrier metadata");if(!proof.clause.origins.isEmpty()){++originProofs;require(proof.clause.origins.size()==1&&proof.clause.origins.iterator().next().source.equals(f.a.primary.get(0).source)&&proof.clause.origins.iterator().next().binder==0&&proof.clause.variables.size()==1&&proof.clause.literals.size()==2&&proof.owner.pool==f.pool,"private rigid Origin and free variable kept in actual initial residual");}else if(proof.support.depth==1)donors.add(proof);}
        require(ContextUniversalSourceAlternativesMatrix.supports(actual).equals(expected)&&originProofs==1&&donors.size()==2&&donors.get(0).clause.equivalent(donors.get(1).clause,ContextGroundProductionRounds.budget(WORK))&&!donors.get(0).support.sources.equals(donors.get(1).support.sources),"EXACT initial Source minima, equivalent independent donor residuals never collapse");ContextUniversalCompoundExchange.check(e,f.x,f.common,16,ContextGroundProductionRounds.budget(WORK));ContextUniversalSignedUnitExchange.check(u.collection.output,f.x,f.common,16,ContextGroundProductionRounds.budget(WORK));require(f.common.items.size()==1&&!f.common.observedStep&&f.common.basis==null,"initial carrier does not promote raw foreign/private knowledge or invent STEP");return new Frame(f.x,order,f.common,f.pools,u.collection.output,e);
    }
    static void positive()throws Exception {ContextUniversalSignedAlternativesMatrix.Fixture f=new ContextUniversalSignedAlternativesMatrix.Fixture(true);ContextUniversalGroupedRounds.Result previous=null;int count=0;for(List<Snapshot> order:ContextUniversalContinuationRefutationRunner.permutations(Arrays.asList(f.a,f.b,f.d))){Frame frame=entry(f,order);ContextUniversalGroupedRounds.Result r=ContextUniversalSeparatePrivateMatrix.continued(frame);f.products(r);if(previous!=null)same(previous,r);previous=r;++count;}for(List<Snapshot> members:Arrays.asList(Arrays.asList(f.b,f.d),Arrays.asList(f.d,f.b))){Snapshot group=ContextProductionNativeBinding.trusted("initial-carrier",members,WORK);for(List<Snapshot> order:Arrays.asList(Arrays.asList(f.a,group),Arrays.asList(group,f.a))){ContextUniversalGroupedRounds.Result r=ContextUniversalSeparatePrivateMatrix.continued(entry(f,order));f.products(r);same(previous,r);++count;}}require(count==10,"six independent and four actual trusted initial handoffs");twoBinders();System.out.println("INITIAL_CARRIER_POSITIVE independentOrders=6 trustedVariants=4 exactCompounds=4 symbolicUnits=0 stableHandoffs=10");}
    static void twoBinders()throws Exception {Snapshot x=bind(true,"!anchor(1); !@u @v a(u,1)&&b(u,v)->r(u,v);"),a=bind(false,"!$u $v a(u,1)&&a(v,1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(p,x,a,WORK);Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> rows=checks(x,Collections.singletonList(a),p,Collections.singletonMap(pool.cut,pool));ContextUniversalCompoundExchange.SessionCollection c=compounds(x,p,rows,256,16,WORK);require(c.collection.collected&&pool.sources.size()==1&&a.primary.get(0).witnesses()==2,"two binders in ONE original physical row are eligible when literals are separate");Set<Origin> origins=new HashSet<>();int count=0;for(ContextUniversalCompoundExchange.ResidualProof proof:c.collection.output.clauses)if(!proof.clause.origins.isEmpty()){origins.addAll(proof.clause.origins);require(proof.support.depth==1&&proof.support.sources.equals(ContextUniversalSourceAlternativesMatrix.sources(x.primary.get(1).source,a.primary.get(0).source)),"same whole-row Source support kept for BOTH distinct binder clauses");++count;}require(c.collection.output.clauses.size()==3&&count==2&&origins.size()==2&&origins.stream().allMatch(o->o.source.equals(a.primary.get(0).source)),"same Source never aliases distinct original binders or residual clauses");}
    static void refusals()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@u p(u);"),good=bind(false,"!@u p(u)&&b(u)->r(u);"),bad=bind(false,"!@u (p(u)&&c(u)->s(u))&&(left(u)||right(u));"),donor=bind(false,"!b(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);ContextUniversalNativeRows.Result badRows=ContextUniversalNativeRows.inspect(x,bad,64,WORK);require(badRows.classified&&!badRows.withinShape&&bad.primary.size()==1&&badRows.rows.get(2).parts.size()==2&&badRows.rows.get(2).parts.stream().anyMatch(part->part.role==ContextUniversalNativeRows.Role.PRODUCER)&&badRows.rows.get(2).parts.stream().anyMatch(part->part.role==ContextUniversalNativeRows.Role.UNSUPPORTED),"ONE actual physical row retains supported AND unsupported clauses, no producer-only projection");
        for(List<Snapshot> order:ContextUniversalContinuationRefutationRunner.permutations(Arrays.asList(good,bad,donor))){Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> rows=checks(x,order,p,Collections.emptyMap());noClosure(rows.get(Cut.of(bad)),"unsupported later row cannot publish earlier supported proof prefix");refused(x,p,rows,"whole family refuses unsupported actual Source regardless of cut order");}
        for(List<Snapshot> members:ContextUniversalContinuationRefutationRunner.permutations(Arrays.asList(good,bad,donor))){Snapshot group=ContextProductionNativeBinding.trusted("unsupported-initial",members,WORK);Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> rows=checks(x,Collections.singletonList(group),p,Collections.emptyMap());require(!rows.get(Cut.of(group)).input.withinShape&&rows.get(Cut.of(group)).input.sources.contains(bad.primary.get(0).source),"trusted grouping retains original unsupported physical Source");noClosure(rows.get(Cut.of(group)),"trust never makes unsupported row eligible");refused(x,p,rows,"trusted whole-row refusal has no initial carrier prefix");}
        Snapshot badX=bind(true,"!anchor(1); !@u p(u); !@u (p(u)&&c(u)->s(u))&&(left(u)||right(u));");Packet badCommon=ContextPrivateWitnessPoolRunner.common(badX);Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> badParent=checks(badX,Collections.singletonList(donor),badCommon,Collections.emptyMap());require(badCommon.items.size()==1&&!badParent.get(Cut.of(badX)).input.withinShape,"a valid primary anchor does not certify unsupported WHOLE X inventory");noClosure(badParent.get(Cut.of(badX)),"unsupported X has no proof prefix");refused(badX,badCommon,badParent,"unsupported original X cannot mint initial carrier from its supported seed");
        Snapshot positive=bind(true,"!p(1);"),negative=bind(false,"!~p(1);");Packet conflictCommon=ContextPrivateWitnessPoolRunner.common(positive);Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> conflict=checks(positive,Collections.singletonList(negative),conflictCommon,Collections.emptyMap());org.kanger.ContextUniversalFrozenConstraints.Result rejected=conflict.get(Cut.of(negative));require(rejected.input.classified&&rejected.input.withinShape&&rejected.closed&&rejected.xRefuted&&!rejected.emptyProofs.isEmpty(),"eligible classified CLOSED rows can still be a real sourced contradiction");refused(positive,conflictCommon,conflict,"closed refutation is not ready initial carrier or consistency receipt");
        ContextUniversalNativeRows.Result cap=ContextUniversalNativeRows.inspect(x,bad,2,WORK),work=ContextUniversalNativeRows.inspect(x,bad,64,1);require(!cap.classified&&cap.rows.isEmpty()&&cap.sources.isEmpty()&&!work.classified&&work.rows.isEmpty()&&work.sources.isEmpty(),"native row/work limits expose no classified inventory prefix");
        ContextUniversalSignedAlternativesMatrix.Fixture f=new ContextUniversalSignedAlternativesMatrix.Fixture(true);List<Snapshot> order=Arrays.asList(f.b,f.d,f.a);Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> missing=checks(f.x,order,f.common,Collections.emptyMap());noClosure(missing.get(f.pool.cut),"classified witness is not ready without actual original private pool");refused(f.x,f.common,missing,"late missing private pool invalidates complete initial family");Packet equal=ContextPrivateWitnessPoolRunner.common(f.x);Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> wrong=checks(f.x,order,equal,f.pools);noClosure(wrong.get(f.pool.cut),"equal data cannot replace actual private/common identity");refused(f.x,equal,wrong,"wrong actual common cannot obtain initial carrier");
        Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> valid=checks(f.x,order,f.common,f.pools);ContextUniversalCompoundExchange.SessionCollection alternatives=compounds(f.x,f.common,valid,1,16,WORK),depth=compounds(f.x,f.common,valid,256,0,WORK),smallWork=compounds(f.x,f.common,valid,256,16,1);for(ContextUniversalCompoundExchange.SessionCollection c:Arrays.asList(alternatives,depth,smallWork))require(!c.collection.collected&&c.collection.output==null&&c.metrics.entries==0,"initial alternative/depth/work refusal never returns partial compound carrier");ContextUniversalSignedUnitExchange.SessionCollection empty=units(f.x,f.common,valid);require(empty.collection.collected&&empty.collection.output.units.isEmpty(),"empty unit carrier is valid but NOT complete initial readiness");SessionRun absent=ContextUniversalGroupedRounds.runWithValidationReuse(f.x,order,f.common,f.pools,empty.collection.output,null,ContextUniversalGroupedRoundsRunner.limits(16),ContextUniversalGroupedRoundsRunner.local(),8,WORK,4096);incomplete(absent,"empty symbolic receipt cannot substitute missing mandatory compound carrier");require(absent.result.phase.equals("preflight"),"missing compound refused before derivation");
        for(String text:Arrays.asList("!$u seed(u,1)&&~flag(u,1);","!$u $v pair(u,v);")){Snapshot a=bind(false,text);ContextUniversalNativeRows.Result classified=ContextUniversalNativeRows.inspect(x,a,64,WORK);require(classified.classified&&classified.rows.get(2).parts.size()==1,"whole witness inventory never splits into invented producer clauses");require(classified.withinShape==text.contains("pair("),"classification and transport readiness are distinct, signed witness unsupported");boolean failed=false;try{ContextWitnessResultTransport.privatePool(p,x,a,WORK);}catch(IllegalStateException|IllegalArgumentException expected){failed=true;}require(failed,"signed/multiple-Origin literal refuses actual private transport, no guessed pool");Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> rows=checks(x,Collections.singletonList(a),p,Collections.emptyMap());noClosure(rows.get(Cut.of(a)),"classification alone cannot run without actual supported witness pool");refused(x,p,rows,"unready witness cannot mint initial carriers");}
        System.out.println("INITIAL_CARRIER_REFUSALS independentOrders=6 trustedMemberOrders=6 mixedWholeSource=true missingPrivate=true wrongCommon=true witnessReadiness=true boundedNoPrefix=true");
    }
    static void originHandoff()throws Exception {ContextUniversalSignedAlternativesMatrix.Fixture f=new ContextUniversalSignedAlternativesMatrix.Fixture(true);Frame frame=entry(f,Arrays.asList(f.a,f.b,f.d));ContextUniversalFrozenConstraints.SessionClosure base=ContextUniversalFrozenConstraints.closeSignedCompoundsWithValidationReuse(ContextUniversalCompoundExchangeRunner.rows(f.x,f.b),f.common,null,frame.units,frame.compounds,16,16,512,256,WORK,4096);require(base.result.closed&&!base.result.xRefuted&&base.metrics.entries==0,base.result.reason);ConstraintTransfer legacy=ContextWitnessResultTransport.transferConstraints(base.result,f.common,16,WORK);require(!legacy.transferred&&legacy.output==null&&legacy.local==null&&legacy.privateAfter==null&&legacy.bindings==null&&legacy.certificate==null&&legacy.reason.contains("Unbound or nonfixed typed transport argument"),"unbound legacy path refuses imported Origin with NO product/binding prefix");ContextUniversalGroupedLocalRounds.Closure local=ContextUniversalGroupedLocalRounds.runWithValidationReuse(base.result,frame.local,4096);require(local.stable&&ContextUniversalGroupedLocalRounds.sameContents(base.result,local.output.output,ContextGroundProductionRounds.budget(WORK)),"actual local certificate changes no ordinary proof Source-grade contents");ContextWitnessResultTransport.SessionTransfer transfer=ContextWitnessResultTransport.transferConstraintsCertifiedWithValidationReuse(local.output,16,WORK,4096);ConstraintTransfer t=transfer.transfer;require(t.transferred&&t.certificate==local.output&&t.proof==local.output.output&&t.bindings!=null&&t.bindings.coverage==t.proof&&transfer.metrics.entries==0,t.reason);Set<Origin> actual=ContextUniversalPrivateSymbolicMatrix.origins(t.output,"s"),routes=new HashSet<>();for(ContextUniversalOriginBindings.Route route:t.bindings.routes)routes.add(route.origin);require(actual.size()==1&&routes.containsAll(actual)&&actual.iterator().next().source.equals(f.a.primary.get(0).source),"theorem-specific actual binding routes cover imported original private Origin");ContextUniversalSignedProductAudit.SessionBinding bound=ContextUniversalSignedProductAudit.bindWithValidationReuse(t.proof,t,65536,WORK,4096);require(bound.result.bound&&bound.result.coverage==t.proof&&bound.result.transfer==t&&bound.metrics.entries==0,"independent product audit binds actual certificate/parameter/product ownership");require(!t.output.observedStep&&t.output.basis==null&&t.output.coveredCut==null&&!ContextUniversalGroupedRoundsRunner.has(t.output,"a")&&!ContextUniversalGroupedRoundsRunner.has(t.output,"b")&&t.output.items.stream().noneMatch(item->item.atom.positive&&(item.atom.predicate.equals("need")||item.atom.predicate.equals("ban"))),"Origin evidence grants no STEP, live writer authority or raw disclosures");System.out.println("INITIAL_CARRIER_ORIGIN legacyRefused=true certifiedSameOrdinaryContents=true actualRoutes=true independentProductBinding=true noWriterAuthority=true");}
}
